import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sigma(n):
    return sum(get_divisors(n))

def tau(n):
    return len(get_divisors(n))

candidates = []
for m in range(2, 31):
    divisors = get_divisors(m)
    s_m = sigma(m)
    t_m = tau(m)

    # Check if s_m is a perfect square
    sqrt_s_m = math.isqrt(s_m)
    if sqrt_s_m * sqrt_s_m == s_m:
        candidates.append({
            'm': m,
            'divisors': divisors,
            'tau(m)': t_m,
            'sigma(m)': s_m
        })

# Print results in a clear format
print("--- Candidates found ---")
for c in candidates:
    print(f"m = {c['m']}, sigma(m) = {c['sigma(m)']}, tau(m) = {c['tau(m)']}")
    print(f"  Divisors: {c['divisors']}")

